CREATE OR REPLACE FUNCTION public.clear_user_history(p_history_source text, p_entity_id uuid, p_row_id uuid, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_row_ids     uuid[];
  v_count       integer;
  v_clear_scope text;
BEGIN
  IF p_history_source NOT IN ('user_change_log', 'user_status_history') THEN
    RAISE EXCEPTION 'clear_user_history: invalid history_source %', p_history_source;
  END IF;

  v_clear_scope := CASE WHEN p_row_id IS NULL THEN 'entity' ELSE 'row' END;

  IF p_history_source = 'user_change_log' THEN
    IF p_row_id IS NOT NULL THEN
      SELECT array_agg(id) INTO v_row_ids FROM user_change_log WHERE user_id = p_entity_id AND id = p_row_id;
    ELSE
      SELECT array_agg(id) INTO v_row_ids FROM user_change_log WHERE user_id = p_entity_id;
    END IF;
  ELSE
    IF p_row_id IS NOT NULL THEN
      SELECT array_agg(id) INTO v_row_ids FROM user_status_history WHERE user_id = p_entity_id AND id = p_row_id;
    ELSE
      SELECT array_agg(id) INTO v_row_ids FROM user_status_history WHERE user_id = p_entity_id;
    END IF;
  END IF;

  v_count := COALESCE(array_length(v_row_ids, 1), 0);

  -- No-op: nothing to clear — no audit row, no delete.
  IF v_count = 0 THEN
    RETURN jsonb_build_object('cleared_row_count', 0, 'cleared_row_ids', '[]'::jsonb);
  END IF;

  -- Audit row FIRST. If the DELETE below raises, this INSERT is rolled back
  -- too (same function call = same unit of the calling transaction).
  INSERT INTO history_clear_events (
    actor_user_id, entity_type, entity_id, history_source, clear_scope, cleared_row_ids, cleared_row_count
  ) VALUES (
    p_actor_user_id, 'user', p_entity_id, p_history_source, v_clear_scope, v_row_ids, v_count
  );

  IF p_history_source = 'user_change_log' THEN
    DELETE FROM user_change_log WHERE id = ANY(v_row_ids);
  ELSE
    DELETE FROM user_status_history WHERE id = ANY(v_row_ids);
  END IF;

  RETURN jsonb_build_object('cleared_row_count', v_count, 'cleared_row_ids', to_jsonb(v_row_ids));
END;
$function$

CREATE OR REPLACE FUNCTION public.end_user_sessions(p_user uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_n integer;
begin
  delete from auth.sessions where user_id = p_user;
  get diagnostics v_n = row_count;
  return v_n;
end $function$

CREATE OR REPLACE FUNCTION public.get_listing_owner_contact(listing_id_param uuid)
 RETURNS TABLE(phone text, whatsapp text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception 'unauthenticated' using errcode = '42501'; end if;
  if not public.caller_is_active() then raise exception 'account_blocked' using errcode = '42501'; end if;
  if not exists (select 1 from public.listings l join public.users u on u.id = l.user_id
                 where l.id = listing_id_param and l.status = 'active' and u.deleted_at is null) then
    return;
  end if;
  return query
    select u.phone, u.whatsapp from public.listings l join public.users u on u.id = l.user_id
    where l.id = listing_id_param and l.status = 'active' and u.deleted_at is null;
end $function$

CREATE OR REPLACE FUNCTION public.listing_contact_events_set_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_owner uuid;
begin
  select l.user_id
    into v_owner
  from public.listings l
  where l.id = new.listing_id;

  if v_owner is null then
    raise exception 'listing_contact_events: listing % does not exist', new.listing_id
      using errcode = 'foreign_key_violation';
  end if;

  new.listing_owner_id := v_owner;
  new.is_owner_click   := (new.actor_user_id is not null and new.actor_user_id = v_owner);
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.listings_price_rule()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if tg_op = 'INSERT' then
    new.price_initial := new.price;
    new.price_old := null;
    return new;
  end if;
  if new.currency is distinct from old.currency then
    -- R64 (a): BLOCKED (the database holds no live rate to convert at, see the file's change 12). FAIL-SAFE, not in the kickoff: the new price starts a new starting price and no old price is
    -- shown, so a price in one currency is never compared with a starting price in another.
    new.price_initial := new.price;
    new.price_old := null;
    return new;
  end if;
  new.price_initial := old.price_initial;
  new.price_old := case when old.price_initial is not null and new.price < old.price_initial then old.price_initial else null end;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.record_listing_view(p_listing_id uuid, p_user_id uuid DEFAULT NULL::uuid, p_ip_hash text DEFAULT ''::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_hash text := left(coalesce(p_ip_hash, ''), 64);
begin
  -- same statuses as the view route (src/app/api/listings/[slug]/view/route.ts)
  if not exists (select 1 from listings where id = p_listing_id and status in ('active', 'sold', 'rented', 'archived')) then return false; end if;
  if p_user_id is null and v_hash = '' then return false; end if;   -- nothing to de-duplicate by: not counted
  perform pg_advisory_xact_lock(hashtextextended(p_listing_id::text || '|' || coalesce(p_user_id::text, 'ip:' || v_hash), 0));
  if exists (
    select 1 from listing_views
    where listing_id = p_listing_id and viewed_at >= now() - interval '24 hours'
      and ((p_user_id is not null and user_id = p_user_id) or (p_user_id is null and ip_hash = v_hash))
  ) then return false; end if;
  insert into listing_views (listing_id, user_id, ip_hash, viewed_at) values (p_listing_id, p_user_id, v_hash, now());
  update listings set views_count = views_count + 1 where id = p_listing_id;
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.record_recently_viewed(p_listing_id uuid, p_cap integer DEFAULT 25)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_cap integer := least(greatest(coalesce(p_cap, 25), 1), 100);
begin
  if v_user_id is null then raise exception 'unauthenticated'; end if;
  if not public.caller_is_active() then raise exception 'account_blocked' using errcode = '42501'; end if;
  insert into recently_viewed (user_id, listing_id, viewed_at) values (v_user_id, p_listing_id, now())
  on conflict (user_id, listing_id) do update set viewed_at = now();
  delete from recently_viewed
  where user_id = v_user_id
    and id not in (select id from recently_viewed where user_id = v_user_id order by viewed_at desc limit v_cap);
end $function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$
